import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.iXqqCa-C.js";const i="/images/agent-memory-notes.webp",p=JSON.parse('{"title":"记忆","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/memory.md","filePath":"guide/agent/memory.md","lastUpdated":1793501934000}'),l={name:"guide/agent/memory.md"};function n(s,a,d,m,g,_){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h1><p>对话变长后，较早的消息会超出模型的上下文窗口，界面上出现<a href="/guide/agent/chat#消息">上下文边界</a>。记忆功能让角色回顾边界以外的内容。</p><p>记忆按<strong>单个会话</strong>独立开启，在「记忆」标签页的「长期记忆实现」中选择「便签压缩」或「关闭」。</p><h2 id="便签压缩" tabindex="-1">便签压缩 <a class="header-anchor" href="#便签压缩" aria-label="Permalink to &quot;便签压缩&quot;">​</a></h2><p>AI 模型把较早的对话压缩成一条条「便签」摘要，对话超出上下文窗口后，角色通过便签回顾之前的内容。</p><ul><li>每条便签覆盖一段对话区间，可以点开查看起止消息并跳转定位。</li><li>便签支持<strong>手动编辑、调整顺序、删除</strong>。删除后，对应区间的消息会重新以原文进入对话历史。</li><li>便签有状态：生成中 / 参与回复 / 休眠中 / 失败。压缩失败时会在会话中提示，可整体重试；已生成的便签可以手动编辑修正。</li><li>「记忆」页有消息分段总览，自上而下由新到旧，显示哪些消息在窗口内、哪些在排队、哪些已被总结。</li><li>可以为会话单独选择<strong>压缩模型</strong>，便签摘要按所选模型<strong>单独计费</strong>（扣费时机可能与当轮回复略有先后）。</li><li>切换压缩模型会<strong>清空当前会话的已有便签</strong>，之后重新压缩。</li></ul><p><img src="'+i+'" alt="便签压缩"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>记忆随会话隔离：A 会话的记忆不会进入 B 会话。</li><li><strong>删除会话</strong>时会同时删除该会话的便签，且不可恢复；如需保留，先导出聊天记录。</li><li>便签是摘要，不是原文。</li></ul>',9)])])}const h=e(l,[["render",n]]);export{p as __pageData,h as default};
